codeExamples.code:
# templates/_helpers.tpl
{{- define "orders.fullname" -}}
{{- printf "%s-%s" .Release.Name .Chart.Name | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- define "orders.labels" -}}
app.kubernetes.io/name: {{ .Chart.Name }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion }}
{{- end -}}

# templates/cronjob.yaml
{{- if .Values.nightlyLoad.enabled }}
apiVersion: batch/v1
kind: CronJob
metadata:
  name: {{ include "orders.fullname" . }}-nightly
  labels:
    {{- include "orders.labels" . | nindent 4 }}
spec:
  schedule: {{ .Values.nightlyLoad.schedule | quote }}
  concurrencyPolicy: Forbid
  jobTemplate:
    spec:
      template:
        spec:
          restartPolicy: Never
          containers:
            - name: loader
              image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
              args: ["python", "load_orders.py"]
              resources:
                {{- toYaml .Values.resources | nindent 16 }}
{{- end }}
